liquidMetalBorder.glsl:
precision mediump float;
uniform vec2 u_resolution;
uniform float u_time;
void main() {
  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
  float noise = sin(uv.x * 12.0 + u_time * 2.0) * cos(uv.y * 12.0 + u_time * 1.5);
  vec3 color = vec3(0.5 + 0.5 * sin(u_time + uv.xyx + vec3(0,2,4))) + noise * 0.15;
  gl_FragColor = vec4(color, 1.0);
}
